argv:
set timeout 90
spawn env QWEN_TUI_RENDERER=opentui QWEN_CODE_SKIP_UPDATE_CHECK_ONCE=true bun packages/cli/dist/index.js
expect { -re {ready} {} -re {TextNodeRenderable only accepts|unexpected critical error|Error:} { exit 1 } timeout { exit 2 } }
send -- "/help\r"
expect { -re {For more help:} {} -re {TextNodeRenderable only accepts|unexpected critical error|Error:} { exit 3 } timeout { exit 4 } }
send -- "\033"
after 500
send -- "\003"
expect { eof {} timeout { exit 5 } }
